//! The Library: the font set and the asset map a graphic draws with, built
//! from bytes the caller read (G-2, G-6 — never `load_system_fonts`), its
//! content version, the `measure_text` memo, and the usvg options every
//! parse shares, whose resolvers record what resvg itself never reports.
//! The generic families `serif`, `sans-serif` and `monospace` are named on
//! the database (G-6), and a font is chosen from the text's OWN families
//! only, never usvg's appended `serif` fallback.

use std::collections::{BTreeMap, HashMap};
use std::sync::{Arc, Mutex, MutexGuard};

use resvg::usvg;
use resvg::usvg::fontdb;
use sha2::{Digest, Sha256};

use crate::diagnostic::Diagnostic;
use crate::images::{cached_kind, Asset};
use crate::measure::{FontStyle, TextMetrics};

/// `(family, size bits, weight, style, letter-spacing bits, preserve, text)`.
pub(crate) type MemoKey = (String, u64, u16, FontStyle, u64, bool, String);

/// The memo is cleared when it reaches this many entries.
const MEMO_CAP: usize = 4096;

/// The engine's fonts and assets. Immutable once built; `Send + Sync`.
pub struct Library {
    db: Arc<fontdb::Database>,
    assets: BTreeMap<String, Asset>,
    families: Vec<String>,
    version: String,
    warnings: Vec<Diagnostic>,
    memo: Mutex<HashMap<MemoKey, TextMetrics>>,
}

/// One loaded face.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Face {
    pub family: String,
    pub post_script_name: String,
    pub weight: u16,
    pub italic: bool,
}

/// What one parse's resolvers saw: the family lists no face answered, the
/// hrefs that name no asset, whether a data: URL was met, and the assets
/// that are not images.
#[derive(Default)]
pub(crate) struct Probe {
    pub(crate) families: Vec<Vec<usvg::FontFamily>>,
    pub(crate) hrefs: Vec<String>,
    pub(crate) data_url: bool,
    pub(crate) bad_assets: Vec<String>,
}

/// Every closure takes the lock only for its own push: a nested SVG asset
/// re-enters `select_font` on the same thread, and the lock is not
/// re-entrant.
pub(crate) fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

impl Library {
    pub fn new(fonts: Vec<Vec<u8>>, assets: BTreeMap<String, Vec<u8>>) -> Library {
        let version = version_of(&fonts, &assets);
        let mut db = fontdb::Database::new();
        let mut warnings = Vec::new();
        for (index, bytes) in fonts.into_iter().enumerate() {
            let before = db.len();
            db.load_font_data(bytes);
            if db.len() == before {
                warnings.push(Diagnostic::warning(format!("font {index} loaded no face")));
            }
        }
        // G-6's generics; `cursive` and `fantasy` keep fontdb's defaults,
        // which the set lacks, so they are warned like any missing family.
        db.set_serif_family("Source Serif 4");
        db.set_sans_serif_family("Source Sans 3");
        db.set_monospace_family("IBM Plex Mono");
        let mut families: Vec<String> = db
            .faces()
            .filter_map(|face| face.families.first().map(|(name, _)| name.clone()))
            .collect();
        families.sort();
        families.dedup();
        Library {
            db: Arc::new(db),
            assets: assets
                .into_iter()
                .map(|(name, data)| {
                    let digest = Sha256::digest(&data).into();
                    let data = Arc::new(data);
                    (name, Asset { data, digest })
                })
                .collect(),
            families,
            version,
            warnings,
            memo: Mutex::new(HashMap::new()),
        }
    }

    /// Primary family names, sorted and deduplicated.
    pub fn families(&self) -> &[String] {
        &self.families
    }

    pub fn faces(&self) -> Vec<Face> {
        self.db
            .faces()
            .map(|face| Face {
                family: face
                    .families
                    .first()
                    .map(|(name, _)| name.clone())
                    .unwrap_or_default(),
                post_script_name: face.post_script_name.clone(),
                weight: face.weight.0,
                italic: face.style != fontdb::Style::Normal,
            })
            .collect()
    }

    pub fn asset_names(&self) -> Vec<&str> {
        self.assets.keys().map(String::as_str).collect()
    }

    pub fn asset(&self, name: &str) -> Option<&[u8]> {
        self.assets.get(name).map(|asset| asset.data.as_slice())
    }

    /// SHA-256 of the font and asset bytes, 64 lowercase hex characters.
    pub fn version(&self) -> &str {
        &self.version
    }

    /// One per font blob that loaded no face.
    pub fn warnings(&self) -> &[Diagnostic] {
        &self.warnings
    }

    pub(crate) fn memo_get(&self, key: &MemoKey) -> Option<TextMetrics> {
        lock(&self.memo).get(key).copied()
    }

    pub(crate) fn memo_put(&self, key: MemoKey, metrics: TextMetrics) {
        let mut memo = lock(&self.memo);
        if memo.len() >= MEMO_CAP {
            memo.clear();
        }
        memo.insert(key, metrics);
    }

    /// The options every parse uses: this font set only, `<image>` hrefs
    /// answered from the asset map only, and every miss recorded in
    /// `probe`. `Options` is not `Clone`, so each call builds its own.
    pub(crate) fn options<'a>(&'a self, probe: &'a Mutex<Probe>) -> usvg::Options<'a> {
        let select_font: usvg::FontSelectionFn<'a> = Box::new(move |font, db| {
            let id = select_font(font, db);
            if id.is_none() {
                lock(probe).families.push(font.families().to_vec());
            }
            id
        });
        let resolve_data: usvg::ImageHrefDataResolverFn<'a> = Box::new(move |_, _, _| {
            lock(probe).data_url = true;
            None
        });
        let resolve_string: usvg::ImageHrefStringResolverFn<'a> =
            Box::new(move |href, opts| match self.assets.get(href) {
                Some(asset) => {
                    let kind = image_kind(asset, opts);
                    if kind.is_none() {
                        lock(probe).bad_assets.push(href.to_string());
                    }
                    kind
                }
                None => {
                    lock(probe).hrefs.push(href.to_string());
                    None
                }
            });
        usvg::Options {
            fontdb: self.db.clone(),
            font_resolver: usvg::FontResolver {
                select_font,
                select_fallback: usvg::FontResolver::default_fallback_selector(),
            },
            image_href_resolver: usvg::ImageHrefResolver {
                resolve_data,
                resolve_string,
            },
            ..usvg::Options::default()
        }
    }
}

/// usvg's `default_font_selector` without its last line: a query over the
/// text's own families, the generics through the database's mapping. usvg
/// appends `Family::Serif` as a fallback, which with `serif` mapped (G-6)
/// would draw every missing family in Source Serif 4 and never warn. No
/// lock is held here: the caller locks only for its own push.
fn select_font(font: &usvg::Font, db: &fontdb::Database) -> Option<fontdb::ID> {
    let families: Vec<fontdb::Family> = font
        .families()
        .iter()
        .map(|family| match family {
            usvg::FontFamily::Serif => fontdb::Family::Serif,
            usvg::FontFamily::SansSerif => fontdb::Family::SansSerif,
            usvg::FontFamily::Cursive => fontdb::Family::Cursive,
            usvg::FontFamily::Fantasy => fontdb::Family::Fantasy,
            usvg::FontFamily::Monospace => fontdb::Family::Monospace,
            usvg::FontFamily::Named(name) => fontdb::Family::Name(name),
        })
        .collect();
    let stretch = match font.stretch() {
        usvg::FontStretch::UltraCondensed => fontdb::Stretch::UltraCondensed,
        usvg::FontStretch::ExtraCondensed => fontdb::Stretch::ExtraCondensed,
        usvg::FontStretch::Condensed => fontdb::Stretch::Condensed,
        usvg::FontStretch::SemiCondensed => fontdb::Stretch::SemiCondensed,
        usvg::FontStretch::Normal => fontdb::Stretch::Normal,
        usvg::FontStretch::SemiExpanded => fontdb::Stretch::SemiExpanded,
        usvg::FontStretch::Expanded => fontdb::Stretch::Expanded,
        usvg::FontStretch::ExtraExpanded => fontdb::Stretch::ExtraExpanded,
        usvg::FontStretch::UltraExpanded => fontdb::Stretch::UltraExpanded,
    };
    let style = match font.style() {
        usvg::FontStyle::Normal => fontdb::Style::Normal,
        usvg::FontStyle::Italic => fontdb::Style::Italic,
        usvg::FontStyle::Oblique => fontdb::Style::Oblique,
    };
    db.query(&fontdb::Query {
        families: &families,
        weight: fontdb::Weight(font.weight()),
        stretch,
        style,
    })
}

/// An asset's kind by its magic; a PNG or JPEG is the cache's stored copy
/// when it has one (G-39), and anything that is not PNG, JPEG, GIF or WebP
/// is tried as an SVG (gzipped or not), with no lock held.
fn image_kind(asset: &Asset, opts: &usvg::Options) -> Option<usvg::ImageKind> {
    let data = &asset.data;
    let bytes = data.as_slice();
    if bytes.starts_with(&[0x89, 0x50, 0x4E, 0x47]) {
        cached_kind(asset).or_else(|| Some(usvg::ImageKind::PNG(data.clone())))
    } else if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
        cached_kind(asset).or_else(|| Some(usvg::ImageKind::JPEG(data.clone())))
    } else if bytes.starts_with(&[0x47, 0x49, 0x46, 0x38]) {
        Some(usvg::ImageKind::GIF(data.clone()))
    } else if bytes.len() >= 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some(usvg::ImageKind::WEBP(data.clone()))
    } else {
        usvg::Tree::from_data_nested(bytes, opts)
            .ok()
            .map(usvg::ImageKind::SVG)
    }
}

/// Each font's length (u64 LE) then bytes; then each asset in name order:
/// name length, name, data length, data. The length prefixes keep
/// `{"ab": "c"}` and `{"a": "bc"}` apart.
fn version_of(fonts: &[Vec<u8>], assets: &BTreeMap<String, Vec<u8>>) -> String {
    let mut hash = Sha256::new();
    for font in fonts {
        hash.update((font.len() as u64).to_le_bytes());
        hash.update(font);
    }
    for (name, data) in assets {
        hash.update((name.len() as u64).to_le_bytes());
        hash.update(name.as_bytes());
        hash.update((data.len() as u64).to_le_bytes());
        hash.update(data);
    }
    hash.finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}
//! `graphic` — Frame Job's motion-graphics engine (road map 10 §5a). Its
//! drawing half: the font and asset Library, `rasterize` (usvg parse →
//! resvg render → premultiplied BGRA), `measure_text`, and the Diagnostic.
//! Its JavaScript half: a `Module` compiled once, and `svg`, which runs its
//! `render` in a sandboxed QuickJS engine per (thread, module) (§5b, §5c).
//! The crate takes bytes and answers bytes: no file system, environment or
//! network, and no clock but the call deadline in `runtime.rs` (G-2, G-5).
//!
//! Declarations and re-exports only — no implementation lives here.

#![forbid(unsafe_code)]

mod diagnostic;
mod exception;
mod host;
mod images;
mod library;
mod measure;
mod module;
mod props;
mod raster;
mod runtime;
mod sandbox;

pub use diagnostic::{Diagnostic, Level};
pub use images::{
    image_cache_builds, image_cache_bytes, set_image_build_hook, set_image_cache_limit,
    ImageBuildHook,
};
pub use library::{Face, Library};
pub use measure::{measure_text, FontStyle, TextFont, TextMetrics};
pub use module::Module;
pub use props::{overlay, MAX_OPTIONS, MAX_PROPS, MAX_STRING, TYPES};
pub use raster::{rasterize, MAX_SIDE};
pub use runtime::{engine_count, svg, ENGINES_PER_THREAD, HEAP_BYTES, STACK_BYTES, SVG_BYTES};
# graphic/CLAUDE.md — the graphics engine's rules

Applies to everything under `graphic/`, the crate that draws a graphic clip
(road map 10: `designs/adr/roadmap-10-graphics.md`; the full design is
`archive/roadmap-10.md` §5a). Build commands are the root
`CLAUDE.md`'s: `make test` and `make lint` run this crate after the core.
The crate's record is road map 10 §10.4.

## Module map

- `lib.rs` — `#![forbid(unsafe_code)]`, module declarations and re-exports
  only. No implementation code.
- `diagnostic.rs` — `Level`, `Diagnostic` (`{level, message, line, column,
  frame}`, §5b) and its JSON, keys in that order.
- `images.rs` — the decoded-image cache (spec §11 G-39, #127): `Asset
  {data, digest}`, a process-wide `Mutex` map from an asset's own SHA-256
  to `Ready`/`Building`/`Refused`/`Skipped {len}`, `set_image_cache_limit`,
  `image_cache_bytes`, the doc-hidden `image_cache_builds`, `cached_kind`,
  and the builder of a stored-deflate RGBA8 PNG copy, used only when it
  decodes to exactly the original's pixmap and `imagesize` reads the same
  size. No lock is held across a decode, an encode or a usvg call; a
  build writes only while its digest is still `Building`; the default limit
  is 0, so a binary that sets none takes the original route. The doc-hidden
  `set_image_build_hook` installs an `ImageBuildHook` every build calls
  between its two locks with none held, so a test can hold a build there.
- `library.rs` — `Library`: the font set (`fontdb`, from bytes, never
  `load_system_fonts`, G-6) and the asset map (each asset keeps its own
  SHA-256; a PNG or JPEG kind is asked of the cache first), their content `version`
  (SHA-256 with length prefixes), the `measure_text` memo, and the
  crate-private `options()` builder whose resolvers record into a `Probe`
  what resvg never reports. The generic families map to bundled faces
  (`serif` Source Serif 4, `sans-serif` Source Sans 3, `monospace` IBM Plex
  Mono, G-6), and `select_font` queries only the text's own families,
  never usvg's appended serif fallback, so a missing family still draws
  nothing and is warned.
- `raster.rs` — `rasterize`, `MAX_SIDE`, the RGBA→BGRA row copy into the
  caller's strided buffer, and every warning text `rasterize` answers:
  missing family, unparseable `font-family` (the scan of attributes, `style`
  attributes and `<style>` sheets, and the family of a `font` shorthand in
  a `style` attribute or sheet), unknown href, data: URL, non-image
  asset, size mismatch. The texts are load-bearing: tests match them and
  the app shows them on the clip.
- `measure.rs` — `FontStyle`, `TextFont` (with `preserve_space`, the
  `xmlSpace` key, G-22), `TextMetrics`, `measure_text`; a generic family
  is written unquoted.
- `module.rs` — `Module` (`Send + Sync + Clone`, holds no QuickJS object):
  `compile`, the SHA-256 revision (G-13), `meta`/`schema` read through
  `JSON.stringify` in the module's key order (`{}` when not exported),
  `defaults()`, its top-level warnings (`warnings()`, G-21 (b)).
- `runtime.rs` — `Engine` (one QuickJS `Runtime` + `Context` per (thread,
  module), §5b's limits, the interrupt deadline), the `thread_local!` map
  swept by `Weak` before each call, at most `ENGINES_PER_THREAD` (16, spec
  §11 G-21) engines with the least recently used evicted after the call,
  `svg`, `Engine::parse_colours` (the stdlib's `__parseColour` per text
  under one deadline, storing nothing; G-25), `engine_count`, `HEAP_BYTES`,
  `STACK_BYTES`, `SVG_BYTES` (8 MiB, spec §11 G-20 (c)). The crate's one
  clock.
- `sandbox.rs` — the sandbox script (G-5) and the loader that resolves no
  specifier, with `IMPORT_REFUSAL`.
- `exception.rs` — QuickJS error → Diagnostic: `{name}: {message}`, the
  position from `stack` (the module's own frame first), the budget's
  sentences, what `render` returned (a string over `SVG_BYTES` refused by its
  length, before the `<svg` check). The texts are load-bearing.
- `host.rs` — the globals `__measureText`, `__assetNames`, `__warn` and
  `__namedColour` (svgtypes' named-colour table for the stdlib's colour
  parser).
- `props.rs` — `check_schema` (compile, strict; it takes a colour reader,
  which `Module::compile` builds from `Engine::parse_colours` over the
  schema's colour defaults, G-25 (a); a non-boolean `animate` on an entry
  is refused, G-41), `overlay` (render,
  lenient; every surprise a warning; an asset stored as `""` is handed to
  `render` as `null`, silently, G-42) and the schema's limits `MAX_PROPS`,
  `MAX_OPTIONS`, `MAX_STRING` and `TYPES`, which the core restates as
  `GRAPHIC_<X>` (`core/tests/graphic_ffi.rs` pins each pair;
  `tests/reference.rs` pins the numbers the reference states, and its
  typings' key cap).
- `stdlib.js`, `noise.js`, `path.js` — §5c's standard library, evaluated
  as SCRIPTS (globals) in that order before the sandbox; each under 400
  lines. `path.js` is G-31's path helpers (`getLength`,
