        && name.len() <= MAX_NAME
        && !name.starts_with('.')
        && !name.chars().any(|c| c == '/' || is_replaced(c))
}

/// Each run of replaced scalars one `-`, leading `.`s dropped, empty `file`.
fn legalise(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut in_run = false;
    for c in name.chars() {
        if is_replaced(c) {
