    }
    let listed: Vec<Value> = entries
        .iter()
        .map(|entry| {
            json!({
                "path": entry.path,
                "name": entry.name,
                "size": entry.bytes.len(),
                "sha256": hex(&Sha256::digest(entry.bytes)),
            })
        })
        .collect();
