/// A value as a refusal names it; a missing key is `nothing`.
fn shown(value: Option<&Value>) -> String {
    value.map_or_else(|| "nothing".to_string(), Value::to_string)
}

fn string(spec: &Map<String, Value>, key: &str) -> Result<String, String> {
