    assert_eq!(
        paths,
        [
            "fonts/a-b.ttf",
            "assets/red-dot.png",
            "fonts/x-y.otf",
            "fonts/hidden.ttf",
            "fonts/-",
            "fonts/file",
            "assets/Kept Name (1).png",
        ]
    );
    assert_eq!(
        names,
        [
            "a:b.ttf",
            "red\\dot.png",
