    let given = [
        "fonts/a:b.ttf",
        "fonts/a-b.ttf",
        "fonts/a\\b.ttf",
        "assets/a:b.ttf",
    ];
    let (paths, names) = names_of(&dir, &given);
    assert_eq!(
