fn package() -> (Value, Vec<u8>) {
    let spec = json!({
        "module": "lower-third",
        "title": "Lower third",
        "category": "Titles & Text",
        "description": null,
        "app_version": "0.3.19",
        "files": [
            {"path": "lower-third.js", "size": MODULE.len()},
            {"path": "fonts/Anton.ttf", "size": FONT.len()},
            {"path": "assets/red.png", "size": PNG.len()},
