        }
        let diagnostics = takeDiagnostics(diag)
        guard ok else { throw GraphicFailure(diagnostics: diagnostics) }
        return GraphicRaster(
            width: width, height: height, stride: stride, bgra: bgra, warnings: diagnostics)
    }
}

