    /// arithmetic on a long take, which main must not be doing (SY-22). Each
    /// hops back through `onMain` for every
    /// document touch, so the single-mutation-point rule is untouched.
    ///
    /// The criterion is NOT "touches the disk", which is why
    /// `detect_silence`, `consolidate_media`, `import_captions` and
    /// `export_captions` are all absent: each reads or writes a file on the
    /// main thread and each says so in its own handler.
    private static let productOffMainTools: Set<String> = [
        "import_media", "relink_media", "render_frame", "export", "save_project", "new_project",
        "transcribe", "record_screen", "render_graphic", "open_project", "sync_audio",
        "transcribe_for_fillers", "get_transcript",
    ]
    // The dev tools' members join here (AgentServer+DevTools.swift).
    static let offMainTools = productOffMainTools.union(devOffMainTools)

    // MARK: - Lifecycle
    /// One entry per row of the op table (spec §6, and the module doc of
    /// `core/src/edit.rs`) plus the thirty-eight tools that are not ops: the
    /// project-level ones spec §7.9 names, the five view-state and history
    /// mirrors beside them (`set_range`, `set_selection`, `set_scope`,
    /// `undo`, `redo`), the composites later phases added —
    /// `detect_silence`, `transcribe`, `get_transcript`, `import_captions`, `export_captions`,
    /// `normalize_clip`, `sync_audio` — road map 3's `record_screen`, and road map 10's
    /// eleven graphics tools (`write_graphic`, `get_graphic`,
    /// `graphic_reference`, `render_graphic`, `import_graphic_font`,
    /// `import_graphic_asset`, `delete_graphic`, `rename_graphic`,
    /// `restore_graphic`, `list_graphics`, `insert_graphic`). The count is
    /// not decoration: `prepareCatalog()`'s parity check reads the core's own
    /// `rc_op_names` and holds an explicit allow-list for the ops that
    /// deliberately have no tool, so a new tool that is not an op belongs in
    /// that sentence as well as in this table.
